import re
from typing import Dict

def parse_ini(text: str) -> Dict[str, Dict[str, str]]:
    def resolve_key(section: str, key: str) -> str:
        parts = key.split(':', 1)
        if len(parts) == 1:
            return sections.get(section, {}).get(key)
        else:
            sec, k = parts
            return resolve_key(sec, k)

    lines = text.splitlines()
    sections = {}
    current_section = 'DEFAULT'
    result = {}

    key_pattern = re.compile(r'^\s*([\w-]+)\s*(?:=[^=]+|:)\s*$', re.IGNORECASE)
    comment_pattern = re.compile(r'^\s*;.*|^\s*#\s*.*$', re.IGNORECASE)

    i = 0
    while i < len(lines):
        line = lines[i].strip()
        if not line or comment_pattern.match(line):
            i += 1
            continue

        if line.startswith('[') and line.endswith(']'):
            sec_name = line[1:-1]
            if sec_name == '':
                raise ValueError("Empty section name")
            current_section = sec_name
            result[current_section] = {}
            i += 1
            continue

        match = key_pattern.match(line)
        if not match:
            raise ValueError("Malformed line")

        key, raw_value = match.groups()
        value = raw_value[1:].rstrip() if value[0] in ('"', "'") else raw_value

        if current_section not in result:
            result[current_section] = {}

        result[current_section][key.lower()] = value
        i += 1

    # Handle interpolation
    def resolve_key_recursive(section: str, key: str) -> str:
        nonlocal result
        value = resolve_key(section, key)
        while '${' in value:
            value = re.sub(r'\$\{([^}]+)\}', lambda m: resolve_key_recursive(section, m.group(1)), value)
        return value

    for sec, keys in result.items():
        for k in keys:
            result[sec][k] = resolve_key_recursive(sec, k)

    return result
