from collections import OrderedDict
from typing import Callable, Dict, Any, Optional
import time

class TTLCache:
    def __init__(self, capacity: int, ttl: float, clock: Callable[[], float]):
        self.capacity = capacity
        self.ttl = ttl
        self.clock = clock
        self.cache: OrderedDict[Any, Dict[str, Any]] = OrderedDict()
        self.stats: Dict[str, int] = {"hits": 0, "misses": 0, "evictions": 0, "expirations": 0}

    def _evict_expired(self) -> None:
        now = self.clock()
        while self.cache and now >= self.cache[next(iter(self.cache))]["expiry"]:
            self.cache.popitem(last=False)
            self.stats["expirations"] += 1

    def put(self, key: Any, value: Any) -> None:
        now = self.clock()
        if key in self.cache:
            self.cache.move_to_end(key)
            self.cache[key]["value"] = value
            self.cache[key]["expiry"] = now + self.ttl
            self.stats["hits"] += 1
        else:
            if len(self.cache) >= self.capacity:
                self._evict_expired()
                if len(self.cache) >= self.capacity:
                    self.stats["evictions"] += 1
                    self.cache.popitem(last=False)
            self.cache[key] = {"value": value, "expiry": now + self.ttl}
            self.stats["hits"] += 1

    def get(self, key: Any, default: Optional[Any] = None) -> Any:
        now = self.clock()
        if key not in self.cache:
            self.stats["misses"] += 1
            return default
        if now >= self.cache[key]["expiry"]:
            self.cache.pop(key)
            self.stats["expirations"] += 1
            return default
        self.cache.move_to_end(key)
        self.stats["hits"] += 1
        return self.cache[key]["value"]

    def __len__(self) -> int:
        self._evict_expired()
        return len(self.cache)

    def stats(self) -> Dict[str, int]:
        return self.stats
