from typing import List

def summarize_ranges(nums: List[int]) -> str:
    if not nums:
        return ""

    nums = sorted(set(nums))
    result = []
    i = 0
    while i < len(nums):
        start = nums[i]
        while i + 1 < len(nums) and nums[i] + 1 == nums[i + 1]:
            i += 1
        end = nums[i]

        if end - start >= 2:
            result.append(f"{start}..{end}")
        else:
            result.extend(str(num) for num in nums[start:i+1])

        i += 1

    return ",".join(result)
