from typing import List, Tuple
from decimal import Decimal

def top_customers(rows: List[dict], n: int) -> List[Tuple[str, float]]:
    customer_totals = {}

    for row in rows:
        customer_name = row.get("customer", "").strip()
        amount_str = row.get("amount", "").strip()

        if not customer_name or not amount_str:
            continue

        try:
            amount = Decimal(amount_str.replace('$', '').replace(',', ''))
        except (ValueError, DecimalException):
            continue

        customer_name = customer_name.lower()

        if customer_name not in customer_totals:
            customer_totals[customer_name] = Decimal(0)

        customer_totals[customer_name] += amount

    sorted_customers = sorted(
        customer_totals.items(),
        key=lambda x: (-x[1], x[0])
    )

    return [(name.capitalize(), float(total)) for name, total in sorted_customers[:n]]
